1	package meter
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// assertNotSubscribed 断言状态显示没有已生效订阅：Subscribed 为 false，
10	// 当前套餐条件为零值，也没有待换套餐安排与待取消终止时刻。
11	func assertNotSubscribed(t *testing.T, st AccountStatus) {
12		t.Helper()
13		if st.Subscribed {
14			t.Fatalf("Subscribed = true before activation instant, status = %+v", st)
15		}
16		if st.CurrentTerms != (PlanTerms{}) {
17			t.Fatalf("CurrentTerms = %+v before activation, want zero value", st.CurrentTerms)
18		}
19		if st.PendingChange != nil {
20			t.Fatalf("PendingChange = %+v before activation, want nil", st.PendingChange)
21		}
22		if st.ScheduledEnd != nil {
23			t.Fatalf("ScheduledEnd = %v before activation, want nil", *st.ScheduledEnd)
24		}
25	}
26	
27	// TestStatusFutureSubscriptionWaitsForActivationInstant 验证提前登记的订阅
28	// 在实际开通时刻到达前查询显示未生效，到达开通时刻这一瞬间才显示有效订阅与
29	// 登记时保存的完整套餐条件；等待期间的查询不删除也不提前激活登记。
30	func TestStatusFutureSubscriptionWaitsForActivationInstant(t *testing.T) {
31		s, clk := newTestService(utc(2026, 1, 10, 12, 0))
32		mustPlan(t, s, planDef("a", 1000, 10, 100, 500))
33		mustAccount(t, s, "u")
34		wantTerms := termsOf(planDef("a", 1000, 10, 100, 500))
35		activateAt := utc(2026, 1, 20, 12, 0)
36		mustSubscribe(t, s, "u", "a", activateAt)
37	
38		// 一月十日登记、一月二十日中午才开通：登记当天仍未生效。
39		st, err := s.Status("u")
40		if err != nil {
41			t.Fatal(err)
42		}
43		assertNotSubscribed(t, st)
44	
45		// 开通月份已经开始但当日凌晨仍未到开通时刻：不按开通月份提前生效。
46		clk.t = utc(2026, 1, 20, 0, 0)
47		st, _ = s.Status("u")
48		assertNotSubscribed(t, st)
49	
50		// 等待期间修改套餐定义，随后生效时仍应使用登记时保存的快照。
51		if err := s.UpdatePlan(planDef("a", 9999, 99, 9, 1000)); err != nil {
52			t.Fatal(err)
53		}
54		st, _ = s.Status("u")
55		assertNotSubscribed(t, st)
56	
57		// 等待期间再次开通按已有订阅拒绝；安排换套餐、登记取消返回尚未生效。
58		if err := s.Subscribe("u", "a", utc(2026, 1, 20, 12, 0)); !errors.Is(err, ErrSubscriptionExists) {
59			t.Fatalf("duplicate subscribe while waiting: %v", err)
60		}
61		if _, err := s.SchedulePlanChange("u", "a"); !errors.Is(err, ErrSubscriptionNotActivated) {
62			t.Fatalf("schedule change while waiting: %v", err)
63		}
64		if _, err := s.CancelSubscription("u"); !errors.Is(err, ErrSubscriptionNotActivated) {
65			t.Fatalf("cancel while waiting: %v", err)
66		}
67	
68		// 上述失败与查询都不能删除或提前激活登记。
69		st, _ = s.Status("u")
70		assertNotSubscribed(t, st)
71	
72		// 开通时刻前一秒：仍未生效。
73		clk.t = activateAt.Add(-time.Second)
74		st, _ = s.Status("u")
75		assertNotSubscribed(t, st)
76	
77		// 到达开通时刻这一瞬间：直接查询即显示有效订阅与登记时的完整条件，
78		// 无需先上报用量、安排换套餐或生成账单。
79		clk.t = activateAt
80		st, _ = s.Status("u")
81		if !st.Subscribed {
82			t.Fatalf("Subscribed = false at activation instant, status = %+v", st)
83		}
84		if st.CurrentTerms != wantTerms {
85			t.Fatalf("CurrentTerms = %+v, want snapshot %+v", st.CurrentTerms, wantTerms)
86		}
87		if st.PendingChange != nil || st.ScheduledEnd != nil {
88			t.Fatalf("unexpected pending/end at activation: %+v %v", st.PendingChange, st.ScheduledEnd)
89		}
90	}
91	
92	// TestStatusFutureActivationTimezoneInstant 验证开通时刻按同一瞬间比较：
93	// 用带时区的时钟表示同一时刻，在开通瞬间前后得到与 UTC 时钟一致的结果。
94	func TestStatusFutureActivationTimezoneInstant(t *testing.T) {
95		plusOne := time.FixedZone("UTC+1", 60*60)
96		activateUTC := utc(2026, 1, 20, 12, 0)
97	
